-- UniLib: тестові дані (згенеровано generate_seed.py, seed=42)
-- Бібліотеки НЕ створюються: використовуються ті, що вже є в таблиці library.
-- Запускати один раз на базі, де ще немає цих книг. Усе виконується однією транзакцією.
-- Пароль усіх згенерованих користувачів: test1234

SET client_encoding = 'UTF8';
BEGIN;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM library) THEN
    RAISE EXCEPTION 'Таблиця library порожня: спочатку додайте бібліотеки';
  END IF;
END $$;

