-- Книги. library_id розподіляється рівномірно між бібліотеками, що вже є в базі.
INSERT INTO book (isbn, faculty_id, library_id, category_id, title, publication_year, pages, language, description, amount)
SELECT v.isbn, f.id, l.id, c.id, v.title, v.year, v.pages, v.lang, v.descr, v.amount
