  ('978-966-46392-0-7', 'Філософський факультет', 8613, 'Філософія', 'Соціальна філософія: теорія і практика (вид. 2)', 2020, 513, 'Українська', 'Практичний довідник із теми «соціальна філософія»: стислий виклад теорії, типові задачі та розв''язання, тести для самоперевірки.', 9),
  ('978-966-27187-5-1', NULL, 137, 'Художня література', 'Під зорями Бескидів', 1995, 770, 'Українська', 'Збірка оповідань і новел про життя міста, дорогу та пам''ять. Підходить для позакласного читання.', 5),
  ('978-966-28434-7-7', 'Факультет іноземних мов', 5621, 'Іноземні мови', 'Практична граматика: курс лекцій (вид. 2)', 2006, 268, 'Українська', 'Видання підготовлене на основі лекційного курсу «практична граматика». Підходить для підготовки до семінарів, заліків та іспитів.', 9),
  ('978-966-29293-1-7', 'Факультет журналістики', 4422, 'Журналістика', 'Вступ до курсу «медіаправо»', 2020, 321, 'Українська', 'Видання підготовлене на основі лекційного курсу «медіаправо». Підходить для підготовки до семінарів, заліків та іспитів.', 10),
  ('978-966-26728-8-6', 'Факультет журналістики', 5172, 'Журналістика', 'Інтернет-журналістика: збірник задач', 2020, 578, 'Українська', 'Посібник охоплює ключові розділи курсу «інтернет-журналістика». Матеріал супроводжується прикладами, схемами та переліком рекомендованої літератури.', 6),
  ('978-966-34717-5-4', 'Юридичний факультет', 4256, 'Право', 'Міжнародне право: підручник', 2006, 448, 'Українська', 'Практичний довідник із теми «міжнародне право»: стислий виклад теорії, типові задачі та розв''язання, тести для самоперевірки.', 10),
  ('978-966-15939-9-1', NULL, 8821, 'Художня література', 'Дім на розі', 2000, 879, 'Українська', 'Повість про звичайних людей у незвичайних обставинах, написана простою й образною мовою.', 6),
  ('978-966-72256-9-8', 'Філософський факультет', 9365, 'Філософія', 'Етика для студентів', 2007, 153, 'Українська', 'Практичний довідник із теми «етика»: стислий виклад теорії, типові задачі та розв''язання, тести для самоперевірки.', 3),
  ('978-966-96475-9-7', 'Географічний факультет', 8535, 'Географія', 'Картографія: збірник задач', 2025, 541, 'Українська', 'Видання підготовлене на основі лекційного курсу «картографія». Підходить для підготовки до семінарів, заліків та іспитів.', 8),
  ('978-966-32611-1-9', 'Географічний факультет', 7752, 'Географія', 'Економічна географія: підручник', 2012, 135, 'Українська', 'Посібник охоплює ключові розділи курсу «економічна географія». Матеріал супроводжується прикладами, схемами та переліком рекомендованої літератури.', 2),
  ('978-966-64334-7-6', 'Факультет іноземних мов', 2071, 'Іноземні мови', 'Практична граматика: курс лекцій (вид. 3)', 1999, 619, 'Українська', 'Навчальне видання для студентів. Розглядаються основні поняття, методи та приклади з теми «практична граматика». Містить контрольні питання та завдання для самостійної роботи.', 4),
  ('978-966-48728-2-6', 'Факультет електроніки та комп''ютерних технологій', 9680, 'Програмування', 'Програмування мовою Python: теорія і практика (вид. 2)', 2014, 547, 'Українська', 'Видання підготовлене на основі лекційного курсу «програмування мовою Python». Підходить для підготовки до семінарів, заліків та іспитів.', 8),
  ('978-966-74564-2-9', 'Факультет педагогічної освіти', 4973, 'Педагогіка', 'Дидактика. Навчальний посібник', 1995, 80, 'Українська', 'Видання підготовлене на основі лекційного курсу «дидактика». Підходить для підготовки до семінарів, заліків та іспитів.', 10),
  ('978-966-74064-9-3', 'Біологічний факультет', 3788, 'Біологія', 'Зоологія. Навчальний посібник', 2020, 87, 'Українська', 'Практичний довідник із теми «зоологія»: стислий виклад теорії, типові задачі та розв''язання, тести для самоперевірки.', 10),
  ('978-966-63416-3-4', 'Філософський факультет', 8464, 'Філософія', 'Вступ до курсу «логіка»', 2019, 899, 'Українська', 'Практичний довідник із теми «логіка»: стислий виклад теорії, типові задачі та розв''язання, тести для самоперевірки.', 6)
) AS v(isbn, faculty, lib_n, category, title, year, pages, lang, descr, amount)
JOIN category c ON c.name = v.category
LEFT JOIN faculty f ON f.name = v.faculty
JOIN (SELECT id, row_number() OVER (ORDER BY id) - 1 AS rn, count(*) OVER () AS cnt FROM library) l
  ON l.rn = v.lib_n % l.cnt;

